const r = $input.first().json;
const pct = (v) => (v === null || v === undefined ? 'n/a' : `${Math.round(v * 100)}%`);
const lines = (r.channels || []).map((c) => `- ${c.source}: ${c.signups} signups, ${c.activated} activated (${pct(c.activationRate)}), ${c.activeLast7d} active in 7d`);
const text = [
  `ZOOKA-AI growth, last ${r.days} days`,
  `Signups ${r.totals.signups} | Activated ${r.totals.activated} (${pct(r.totals.activationRate)}) | Active 7d ${r.totals.activeLast7d}`,
  `Best channel: ${r.bestChannel ?? 'none yet'}`,
  '',
  ...lines,
  '',
  `Not measured yet: ${(r.notMeasured || []).join('; ')}`,
].join('\n');
return [{ json: { text, report: r } }];
